/**
 * Study notebooks: flashcards with a simple spaced-repetition schedule, quizzes with saved attempts, and progress.
 * Cards and questions are generated by AI as JSON and validated before anything is saved.
 */
import { newId } from '../store/captures';
import { deleteRecord, getRecord, listRecords, putRecord, updateRecord } from '../store/records';

export interface Card {
  id: string;
  q: string;
  a: string;
  /** When the card is next due (ms). */
  due: number;
  /** Days until the next review after a correct answer. */
  interval: number;
  ease: number;
  reps: number;
  lapses: number;
  captureId?: string;
}

export interface QuizQuestion {
  id: string;
  q: string;
  options: string[];
  answer: number;
  explain?: string;
  captureId?: string;
}

export interface Attempt {
  at: number;
  score: number;
  total: number;
  /** Ids of the questions answered wrongly. */
  wrong: string[];
}

export interface Notebook {
  id: string;
  name: string;
  workspaceId?: string;
  createdAt: number;
  cards: Card[];
  quiz: QuizQuestion[];
  attempts: Attempt[];
}

const DAY = 86_400_000;
const AGAIN_DELAY = 10 * 60_000;
const str = (v: unknown, max: number) => (typeof v === 'string' ? v.trim().replace(/\s+/g, ' ').slice(0, max) : '');
const num = (v: unknown, d: number, min: number, max: number) => (typeof v === 'number' && Number.isFinite(v) ? Math.min(max, Math.max(min, v)) : d);
type Loose = Record<string, unknown> | null | undefined;

export interface StudySet {
  flashcards: Array<{ q: string; a: string }>;
  quiz: Array<{ q: string; options: string[]; answer: number; explain?: string }>;
}

function cleanQuestion(x: Loose): { q: string; options: string[]; answer: number; explain?: string } | null {
  const options = (Array.isArray(x?.options) ? x.options : []).map((v) => str(v, 200)).filter(Boolean).slice(0, 6);
  const raw = x?.answer;
  const answer = typeof raw === 'number' ? raw : typeof raw === 'string' ? 'ABCDEF'.indexOf(raw.trim().toUpperCase().charAt(0)) : -1;
  const q = str(x?.q ?? x?.question, 400);
  if (!q || options.length < 2 || !Number.isInteger(answer) || answer < 0 || answer >= options.length || new Set(options).size !== options.length) return null;
  const explain = str(x?.explain ?? x?.explanation, 400);
  return { q, options, answer, ...(explain ? { explain } : {}) };
}

/** Validates a generated study set (from the AI's JSON reply). Returns null when nothing usable is in it. */
export function parseStudySet(reply: string): StudySet | null {
  const m = /\{[\s\S]*\}/.exec(reply);
  if (!m) return null;
  let o: Record<string, unknown>;
  try {
    o = JSON.parse(m[0]) as Record<string, unknown>;
  } catch {
    return null;
  }
  const flashcards = (Array.isArray(o.flashcards) ? (o.flashcards as Loose[]) : [])
    .map((c) => ({ q: str(c?.q ?? c?.question, 400), a: str(c?.a ?? c?.answer, 800) }))
    .filter((c) => c.q && c.a)
    .slice(0, 30);
  const quiz = (Array.isArray(o.quiz) ? (o.quiz as Loose[]) : []).map(cleanQuestion).filter((x): x is NonNullable<typeof x> => Boolean(x)).slice(0, 20);
  if (!flashcards.length && !quiz.length) return null;
  return { flashcards, quiz };
}

export type Grade = 'again' | 'good' | 'easy';

/** Next state of a card after a review (a light SM-2: again → soon, good → longer, easy → much longer). */
export function review(c: Card, g: Grade, now = Date.now()): Card {
  if (g === 'again') return { ...c, reps: 0, lapses: c.lapses + 1, interval: 0, ease: Math.max(1.3, c.ease - 0.2), due: now + AGAIN_DELAY };
  const interval = g === 'good' ? (c.reps === 0 ? 1 : c.reps === 1 ? 3 : Math.round(Math.max(1, c.interval) * c.ease)) : c.reps === 0 ? 4 : Math.round(Math.max(1, c.interval) * c.ease * 1.3);
  const ease = g === 'easy' ? Math.min(3, c.ease + 0.15) : c.ease;
  return { ...c, reps: c.reps + 1, interval, ease, due: now + interval * DAY };
}

export const dueCards = (nb: Notebook, now = Date.now()) => nb.cards.filter((c) => c.due <= now).sort((a, b) => a.due - b.due);

export interface Progress {
  cards: number;
  due: number;
  learning: number;
  /** Reviewed well enough to wait 3 weeks or more. */
  mastered: number;
  quizzes: number;
  best: number | null;
  last: number | null;
}

export function progress(nb: Notebook, now = Date.now()): Progress {
  const pct = (a: Attempt) => (a.total ? Math.round((a.score / a.total) * 100) : 0);
  return {
    cards: nb.cards.length,
    due: dueCards(nb, now).length,
    learning: nb.cards.filter((c) => c.reps > 0 && c.interval < 21).length,
    mastered: nb.cards.filter((c) => c.interval >= 21).length,
    quizzes: nb.attempts.length,
    best: nb.attempts.length ? Math.max(...nb.attempts.map(pct)) : null,
    last: nb.attempts.length ? pct(nb.attempts[nb.attempts.length - 1]!) : null,
  };
}

/** Scores one quiz attempt; `chosen[i]` is the option picked for question i (or -1). */
export function scoreQuiz(quiz: QuizQuestion[], chosen: number[], now = Date.now()): Attempt {
  const wrong = quiz.filter((q, i) => chosen[i] !== q.answer).map((q) => q.id);
  return { at: now, score: quiz.length - wrong.length, total: quiz.length, wrong };
}

/** The questions most often answered wrongly, for learning-gap suggestions. */
export function weakQuestions(nb: Notebook, max = 10): QuizQuestion[] {
  const count = new Map<string, number>();
  for (const a of nb.attempts) for (const id of a.wrong) count.set(id, (count.get(id) ?? 0) + 1);
  return nb.quiz.filter((q) => count.has(q.id)).sort((a, b) => count.get(b.id)! - count.get(a.id)!).slice(0, max);
}

const idOf = (v: unknown) => (typeof v === 'string' && v && v.length <= 80 ? v : null);

export function validateNotebook(raw: unknown): Notebook | null {
  const r = raw as Record<string, unknown> | null;
  if (!r || typeof r !== 'object' || !idOf(r.id)) return null;
  const name = str(r.name, 80);
  if (!name) return null;
  const cards = (Array.isArray(r.cards) ? (r.cards as Loose[]) : [])
    .map((c): Card | null => {
      const q = str(c?.q, 400);
      const a = str(c?.a, 800);
      const id = idOf(c?.id);
      if (!q || !a || !id) return null;
      const captureId = idOf(c?.captureId);
      return { id, q, a, due: num(c?.due, 0, 0, 8.64e15), interval: num(c?.interval, 0, 0, 3650), ease: num(c?.ease, 2.5, 1.3, 3), reps: Math.round(num(c?.reps, 0, 0, 1e6)), lapses: Math.round(num(c?.lapses, 0, 0, 1e6)), ...(captureId ? { captureId } : {}) };
    })
    .filter((c): c is Card => Boolean(c))
    .slice(0, 2000);
  const quiz = (Array.isArray(r.quiz) ? (r.quiz as Loose[]) : [])
    .map((x): QuizQuestion | null => {
      const id = idOf(x?.id);
      const clean = cleanQuestion(x);
      if (!id || !clean) return null;
      const captureId = idOf(x?.captureId);
      return { id, ...clean, ...(captureId ? { captureId } : {}) };
    })
    .filter((x): x is QuizQuestion => Boolean(x))
    .slice(0, 1000);
  const ids = new Set(quiz.map((q) => q.id));
  const attempts = (Array.isArray(r.attempts) ? (r.attempts as Loose[]) : [])
    .filter((a) => a && typeof a.at === 'number' && typeof a.score === 'number' && typeof a.total === 'number')
    .map((a) => ({ at: a!.at as number, score: Math.max(0, Math.round(a!.score as number)), total: Math.max(0, Math.round(a!.total as number)), wrong: (Array.isArray(a!.wrong) ? a!.wrong : []).filter((w): w is string => typeof w === 'string' && ids.has(w)) }))
    .slice(-500);
  const workspaceId = idOf(r.workspaceId);
  return { id: r.id as string, name, ...(workspaceId ? { workspaceId } : {}), createdAt: num(r.createdAt, Date.now(), 0, 8.64e15), cards, quiz, attempts };
}

export async function listNotebooks(): Promise<Notebook[]> {
  return (await listRecords<unknown>('notebooks')).map(validateNotebook).filter((x): x is Notebook => Boolean(x)).sort((a, b) => a.name.localeCompare(b.name));
}

export const getNotebook = async (id: string) => validateNotebook(await getRecord('notebooks', id)) ?? undefined;

export async function createNotebook(name: string, workspaceId?: string): Promise<Notebook> {
  const nb = validateNotebook({ id: `nb-${newId()}`, name, workspaceId, createdAt: Date.now(), cards: [], quiz: [], attempts: [] });
  if (!nb) throw new Error('Give the notebook a name.');
  return putRecord('notebooks', nb);
}

export const deleteNotebook = (id: string) => deleteRecord('notebooks', id);

/** Adds a generated set to a notebook: new cards are due now. */
export function addStudySet(id: string, set: StudySet, captureId?: string, now = Date.now()) {
  return updateRecord<Notebook>('notebooks', id, (nb) => {
    const extra = captureId ? { captureId } : {};
    nb.cards.push(...set.flashcards.map((c) => ({ id: `c-${newId()}`, q: c.q, a: c.a, due: now, interval: 0, ease: 2.5, reps: 0, lapses: 0, ...extra })));
    nb.quiz.push(...set.quiz.map((q) => ({ id: `q-${newId()}`, ...q, ...extra })));
  });
}

export const gradeCard = (id: string, cardId: string, g: Grade, now = Date.now()) =>
  updateRecord<Notebook>('notebooks', id, (nb) => {
    nb.cards = nb.cards.map((c) => (c.id === cardId ? review(c, g, now) : c));
  });

export const saveAttempt = (id: string, a: Attempt) => updateRecord<Notebook>('notebooks', id, (nb) => void nb.attempts.push(a));
